#!/bin/sh
# SPDX-License-Identifier: BSD-2-Clause
# Copyright 2026 Romain Dolbeau
#
# Make the patched RD68884 that sync_pythondata.sh takes the FPU from:
# ~/LITEX-68K/RD68884 (disposable), a clone of the commit checked out under
# Inputs/RD68884 with patches/RD68884/*.patch applied (git am), and its
# generated microcode (rtl/gen/) regenerated by its own `make ucode` and
# committed, so that the tree is clean.
#
# The patches carry only sources (tools/), not rtl/gen/: regenerated, every
# microcode ROM word after a change moves. `make ucode` needs mpmath, a
# submodule of RD68884 (third_party/mpmath), fetched here from its upstream.
#
# Usage: scripts/patch_rd68884.sh [destination]   (default ~/LITEX-68K/RD68884)
# An existing destination is checked, not remade: it must be that commit plus
# exactly these patches. Remove it to start again.
set -eu

HERE=$(cd "$(dirname "$0")/.." && pwd)
SRC=$HERE/Inputs/RD68884
DST=${1:-$HOME/LITEX-68K/RD68884}
BASE=$(git -C "$SRC" rev-parse HEAD)
PATCHES=$(ls "$HERE"/patches/RD68884/*.patch)
N=$(echo "$PATCHES" | wc -l)
REGEN="Regenerate rtl/gen (make ucode)"

if [ ! -d "$DST" ]; then
    git clone -q "$SRC" "$DST"
    git -C "$DST" checkout -q -B litex-68k "$BASE"
    git -C "$DST" -c user.name=litex-68k -c user.email=litex-68k@localhost \
        am -q $PATCHES
    git -C "$DST" submodule update --init -q third_party/mpmath
    make -C "$DST" -s ucode
    git -C "$DST" add rtl/gen
    git -C "$DST" -c user.name=litex-68k -c user.email=litex-68k@localhost \
        commit -q -m "$REGEN"
fi

# Checked: the base, the patches by subject, then the regeneration; clean.
[ "$(git -C "$DST" rev-parse "HEAD~$((N + 1))")" = "$BASE" ] \
    || { echo "$DST is not Inputs/RD68884 ($BASE) plus the patches" >&2; exit 1; }
WANT=$(for p in $PATCHES; do sed -n 's/^Subject: \[PATCH[^]]*\] //p' "$p"; done)
HAVE=$(git -C "$DST" log --reverse --format=%s "HEAD~$((N + 1))..HEAD~1")
[ "$(echo "$WANT" | cut -c1-40)" = "$(echo "$HAVE" | cut -c1-40)" ] \
    || { echo "$DST has other patches than patches/RD68884" >&2; exit 1; }
[ "$(git -C "$DST" log -1 --format=%s)" = "$REGEN" ] \
    || { echo "$DST: the last commit is not the regeneration" >&2; exit 1; }
[ -z "$(git -C "$DST" status --porcelain --untracked-files=no)" ] \
    || { echo "$DST has local changes" >&2; exit 1; }
make -C "$DST" -s ucode-check
echo "$DST: RD68884 $(git -C "$SRC" describe --always --tags) + $N patch(es)"
